int br_sysfs_addif ( struct net_bridge_port * p ) { struct net_bridge * br = p -> br ; const struct brport_attribute * * a ; int err ; err = sysfs_create_link ( & p -> kobj , & br -> dev -> dev . kobj , SYSFS_BRIDGE_PORT_LINK ) ; if ( err ) { return err ; } for ( a = brport_attrs ; * a ; ++ a ) { err = sysfs_create_file ( & p -> kobj , & ( ( * a ) -> attr ) ) ; if ( err ) { return err ; } } return sysfs_create_link ( br -> ifobj , & p -> kobj , p -> sysfs_name ) ; } 